SELECT id, title, type, discount_rule AS discountRule, status, sort,
       start_time AS startTime, end_time AS endTime
FROM promotion_activity WHERE id = #{id}

SELECT id, title, type, discount_rule AS discountRule, status, sort, start_time AS startTime, end_time AS endTime FROM promotion_activity
AND title LIKE CONCAT('%', #{title}, '%') AND id = #{id}
ORDER BY sort ASC, id ASC
